//! Scheduler tables, generated by `tools/gen_tables.py` from the
//! original executable. Do not edit by hand.
//!
//! These live in `SCRANTIC.EXE`'s data segment rather than in
//! `RESOURCE.001`, so they are baked in here to keep the 16-bit binary
//! out of the run-time requirements. See `docs/SCHEDULER.md`.

/// An entry in the scene catalogue at `ds:0x1756`.
pub struct Scene {
    /// Group id; several entries share one.
    pub id: u16,
    /// Selection weight.
    pub weight: u8,
    /// Position Johnny must be standing in. (0, _) means anywhere.
    pub from: (u8, u8),
    /// Position he ends up in.
    pub to: (u8, u8),
    /// Deducted from the caller's time budget.
    pub cost: u8,
    /// Time-of-day window: playable when `min <= phase < max`.
    pub min_phase: u8,
    pub max_phase: u8,
    /// Story day, or 0 for an everyday scene.
    pub day: u8,
    /// Category bitmask.
    pub mask: u32,
    /// ADS file id and the sequence within it. Sequence 0 is disabled.
    pub ads: u8,
    pub sequence: u8,
}

